import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const DEFAULTS = {
  port: 3000,
  host: '127.0.0.1',
};

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const inputPath = path.join(scriptDir, 'config.json');
const outputPath = path.join(scriptDir, 'config.out.json');

function loadConfig(file) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return {};
    throw err;
  }

  if (raw.trim() === '') return {};

  const parsed = JSON.parse(raw);
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error(`${path.basename(file)} must contain a JSON object`);
  }
  return parsed;
}

const config = loadConfig(inputPath);
const resolved = { ...config };

for (const [key, fallback] of Object.entries(DEFAULTS)) {
  if (resolved[key] === undefined || resolved[key] === null) {
    resolved[key] = fallback;
  }
}

fs.writeFileSync(outputPath, `${JSON.stringify(resolved, null, 2)}\n`, 'utf8');

console.log(`wrote ${path.basename(outputPath)}: ${JSON.stringify(resolved)}`);

